input.command:
$rows = Import-Csv 'data\steam.csv' | ForEach-Object {
  $pos=[int]$_.positive_ratings; $neg=[int]$_.negative_ratings; $tot=$pos+$neg
  $parts=$_.owners -split '-'; $own=([double]$parts[0]+[double]$parts[1])/2
  [pscustomobject]@{
    name=$_.name; pos=$pos; neg=$neg; tot=$tot
    ratio=if($tot){$pos/$tot}else{0}
    own=$own; apt=[int]$_.average_playtime; mpt=[int]$_.median_playtime
    price=[double]$_.price; rev=$own*[double]$_.price
  }
}
"games parsed: $($rows.Count)"
"`n== Top 10 by OWNERS (reach) =="
$rows | Sort-Object own -Descending | Select-Object -First 10 | ForEach-Object { "  {0,-32} own~{1,12:N0}  ratio={2:N2}  apt={3}" -f $_.name.Substring(0,[Math]::Min(30,$_.name.Length)),$_.own,$_.ratio,$_.apt }
"`n== Top 10 by QUALITY (ratio, min 500 reviews) =="
$rows | Where-Object {$_.tot -ge 500} | Sort-Object ratio -Descending | Select-Object -First 10 | ForEach-Object { "  {0,-32} ratio={1:N3}  reviews={2,7}  own~{3:N0}" -f $_.name.Substring(0,[Math]::Min(30,$_.name.Length)),$_.ratio,$_.tot,$_.own }
"`n== Top 10 by EST. REVENUE (owners*price) =="
$rows | Sort-Object rev -Descending | Select-Object -First 10 | ForEach-Object { "  {0,-32} rev~`${1,14:N0}  price={2}  own~{3:N0}" -f $_.name.Substring(0,[Math]::Min(30,$_.name.Length)),$_.rev,$_.price,$_.own }
"`n== Top 10 by ENGAGEMENT (median playtime) =="
$rows | Sort-Object mpt -Descending | Select-Object -First 10 | ForEach-Object { "  {0,-32} median_pt={1,6}min  own~{2:N0}  ratio={3:N2}" -f $_.name.Substring(0,[Math]::Min(30,$_.name.Length)),$_.mpt,$_.own,$_.ratio }
$global:R=$rows

$rows=$global:R
function TopSet($key,$n,[scriptblock]$flt){
  $f = if($flt){ $rows | Where-Object $flt } else { $rows }
  ($f | Sort-Object $key -Descending | Select-Object -First $n).name
}
$sets=@{
 'reach'      = TopSet 'own' 100 $null
 'quality'    = TopSet 'ratio' 100 {$_.tot -ge 500}
 'revenue'    = TopSet 'rev' 100 $null
 'engagement' = TopSet 'mpt' 100 $null
}
"== Jaccard overlap of top-100 lists =="
$keys=$sets.Keys | Sort-Object
for($i=0;$i -lt $keys.Count;$i++){
 for($j=$i+1;$j -lt $keys.Count;$j++){
  $a=$sets[$keys[$i]]; $b=$sets[$keys[$j]]
  $inter=($a | Where-Object {$b -contains $_}).Count
  $uni=($a + $b | Select-Object -Unique).Count
  "  {0,-11} vs {1,-11}: {2,5:N1}%  ({3} shared)" -f $keys[$i],$keys[$j],(100*$inter/$uni),$inter
 }
}
# correlations among the continuous metrics
function Corr($x,$y){
 $mx=($x|Measure-Object -Average).Average; $my=($y|Measure-Object -Average).Average
 $num=0;$dx=0;$dy=0
 for($k=0;$k -lt $x.Count;$k++){ $a=$x[$k]-$mx; $b=$y[$k]-$my; $num+=$a*$b; $dx+=$a*$a; $dy+=$b*$b }
 if($dx -eq 0 -or $dy -eq 0){return 0}
 $num/[Math]::Sqrt($dx*$dy)
}
$sub=$rows | Where-Object {$_.tot -ge 50}
"`n== Pearson r among metrics (games with >=50 reviews, n=$($sub.Count)) =="
"  own  vs ratio : {0:N3}" -f (Corr ($sub.own) ($sub.ratio))
"  own  vs mpt   : {0:N3}" -f (Corr ($sub.own) ($sub.mpt))
"  own  vs rev   : {0:N3}" -f (Corr ($sub.own) ($sub.rev))
"  ratio vs mpt  : {0:N3}" -f (Corr ($sub.ratio) ($sub.mpt))
"  ratio vs rev  : {0:N3}" -f (Corr ($sub.ratio) ($sub.rev))

